-- =================================================================
-- SHOE SHOP POS & INVENTORY SYSTEM - 5-YEAR HISTORICAL DUMMY DATASET
-- Spanning 5 Full Chronological Years (September 2021 – September 2026)
-- Complete Enterprise Footwear Dataset:
--   • 1,250+ Sales Invoices (~Rs. 24,000,000+ Revenue)
--   • 115+ Footwear Products across 16 Shoe Brands & 12 Categories
--   • 60 Customer Profiles with complete contact and city details
--   • 12 Wholesale Footwear Distributors & Tanneries
--   • 85 Purchase Consignments & Stock Inflows
--   • 35 Customer Returns & Exchanges
--   • 15 Supplier Debit Notes & Defect Returns
--   • 150+ Stock Movements & Audit Logs
-- =================================================================

BEGIN;

-- 1. Clean existing records
TRUNCATE TABLE 
  password_reset_tokens,
  stock_movements,
  return_items,
  returns,
  sale_items,
  sales,
  purchase_return_items,
  purchase_returns,
  purchase_items,
  purchases,
  products,
  customers,
  suppliers,
  categories,
  brands,
  company_settings,
  users
CASCADE;

-- 2. Company Settings
